const numNodes = 35;
let nodeClusters = [];
let minWH; // min width, height

function setup() {
	minWH = max(windowWidth, windowHeight)
	createCanvas(minWH, minWH);
	pixelDensity(1);
	frameRate(60);

	nodeClusters = [];
	// NodeCluster(x, y, sze, num, clr, t)
	nodeClusters.push(new NodeCluster(width * 0.25, height * 0.25, minWH * 0.45, 25, "yellow", 1));
	nodeClusters.push(new NodeCluster(width * 0.25, height * 0.75, minWH * 0.45, 25, "white", 2));
	nodeClusters.push(new NodeCluster(width * 0.75, height * 0.25, minWH * 0.45, 25, "cyan", 3));
	nodeClusters.push(new NodeCluster(width * 0.75, height * 0.75, minWH * 0.45, 25, "purple", 4));
}

function draw() {
	background(0);


	// draw gradient background
	drawingContext.save();
	const gradientLin = drawingContext.createLinearGradient(sin(radians(frameCount*4)) * width * 0.5 + width * 0.5, 0, width*0.5, height);
	gradientLin.addColorStop(0.0, "black");
	gradientLin.addColorStop(1.0, "darkred");

	const dx = cos(radians(frameCount*2)) * minWH*0.2;
	const dy = sin(radians(frameCount*2)) * minWH*0.2;
	const gradientRad = drawingContext.createRadialGradient(
		width*0.5+dx*0.5, height*0.5+dy*0.5, minWH * 0.2, 
		width*0.5-dx, height*0.5-dy, minWH * 0.65);
	gradientRad.addColorStop(0, "darkred");
	gradientRad.addColorStop(0.49, "black");

	drawingContext.fillStyle = gradientRad; // gradientLin
	noStroke();
	rect(0, 0, width, height)
	drawingContext.fillStyle = null;
	drawingContext.restore();

	// draw node-lusters
	for (let nc of nodeClusters) {
		nc.show();
		nc.animateNodes();
	}

	// // noLoop() removed for animation
}

class NodeCluster {
	// 300, 300, 200, 25, "cyan", 1
	constructor(x, y, sze, num, clr, t = 1) {
		this.x = x;  // center x
		this.y = y;  // center y
		this.sze = sze;  // size
		this.num = num;  // num of nodes
		this.clr = clr;  // color
		this.t = t;  // type
		this.n = []; // nodes
		this.c = []; // connections

		// console.log(this);		
		this.generateNodes();
		this.generateConnections();
	}

	generateNodes() {
		this.n = [];
		const h_S = this.sze * 0.55;
		for (let i = 0; i < this.num; i++) {
			let x, y, a = 0;

			if (this.t === 1) {
				// type = 1: inside the circle
				x = random(-this.sze, this.sze);
				y = random(-this.sze, this.sze);
				a = random() < 0.5 ? 1 : -1; // a is direction of movement

			} else if (this.t === 2) {
				// type = 2: at the edge of the circle
				a = random(TWO_PI) // a is the angle
				x = cos(a) * h_S;
				y = sin(a) * h_S;

			} else {
				// type = 3 + 4: at the edge of the square
				a = random() < 0.5 ? 1 : -1; // a is direction of movement
				if (i % 2) {
					// vertical
					x = random(-h_S, h_S)
					y = random() < 0.5 ? -h_S : h_S;
				} else {
					// horicontal
					x = random() < 0.5 ? -h_S : h_S;
					y = random(-h_S, h_S)
				}
			}
			this.n.push({x, y, i, a});
		}
		// console.log(">generateNodes(): " + this.n.length);
	}

	generateConnections() {
		this.c = [];
		for (let i = 0; i < this.n.length - 1; i++) {
			for (let j = i + 1; j < this.n.length; j++) {
				this.c.push({i, j});
			}
		}
		// console.log(">generateConnections(): " + this.c.length);
	}

	animateNodes() {
		var h_S = this.sze * 0.55;
		for (let i = 0; i < this.num; i++) {
			var x = this.n[i].x;
			let y = this.n[i].y;
			let a = this.n[i].a

			// type = 1: inside the circle
			if (this.t === 1) {
				// move horicontal or vertical (depending on index)
				if (i % 2) {
					if (x + a > h_S || x + a < -h_S) a = -a;
					x += a;
				} else {
					if (y + a > h_S || y + a < -h_S) a = -a;
					y += a;
				}

			// type = 2: at the edge of the circle
			} else if (this.t === 2) {
				// move the angle (depending on index)
				const dir = i % 2 ? 1 : -1; // direction by index
				const da = 0.01 * dir;
				a = this.n[i].a + da;
				x = cos(a) * h_S;
				y = sin(a) * h_S;

			// type = 3: edge of square
			} else if (this.t === 3) {
				// keep nodes at the edges
				if (!(i % 2)) {
					if (y + a > h_S || y + a < -h_S) a = -a;
					y += a;
				} else {
					if (x + a > h_S || x + a < -h_S) a = -a;
					x += a;
				}

			// type = 4: edge of square
			} else {
				// keep distribution, but move between the edges
				if (i % 2) {
					if (y + a > h_S || y + a < -h_S) a = -a;
					y += a;
				} else {
					if (x + a > h_S || x + a < -h_S) a = -a;
					x += a;
				}
			}
			this.n[i] = {x, y, i, a};
		}
	}

	show() {
		// clipping area
		drawingContext.save(); // save the state

		translate(this.x, this.y);

		// black circle + clip
		noStroke();
		fill("whatever"); // strange: do not delete, else circle is not black (why ever)
		fill(0); // here the circle background gets black
		circle(0, 0, this.sze);
		// drawingContext.arc(0, 0, this.sze * 0.5, 0, TWO_PI); // issue: sometimes only (big) pie is cropped
		drawingContext.clip();

		// show connections
		let c = color(this.clr);
		c.setAlpha(64)
		stroke(c);
		blendMode(ADD)
		for (let c of this.c) {
			strokeWeight(noise(c.i * 0.021, frameCount * 0.011) * 1.5); // 0.25
			line(this.n[c.i].x, this.n[c.i].y, this.n[c.j].x, this.n[c.j].y);
		}

		// restore
		drawingContext.restore() // restore to latest state
	}
}
